package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="spms_monitoring_evidence")public class PerformanceMonitoringEvidence extends RspAuditedEntity{public enum Status{ACTIVE,SUPERSEDED,VOIDED}@Column(name="monitoring_case_id",nullable=false,length=36)private String monitoringCaseId;@Column(name="monitoring_update_id",nullable=false,length=36)private String monitoringUpdateId;@Column(name="commitment_item_id",nullable=false,length=36)private String commitmentItemId;@Column(name="original_filename",nullable=false,length=255)private String originalFilename;@Column(name="storage_provider",nullable=false,length=30)private String storageProvider;@Column(name="storage_object_key",nullable=false,length=500)private String storageObjectKey;@Column(name="media_type",nullable=false,length=120)private String mediaType;@Column(name="byte_size",nullable=false)private long byteSize;@Column(nullable=false,length=64)private String checksum;@Column(nullable=false,length=30)private String confidentiality;@Column(name="supersedes_id",length=36)private String supersedesId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="void_reason",length=2000)private String voidReason;@Column(name="uploaded_by",nullable=false,length=100)private String uploadedBy;@Column(name="uploaded_at",nullable=false)private Instant uploadedAt;protected PerformanceMonitoringEvidence(){}public PerformanceMonitoringEvidence(String a,String c,String u,String item,String filename,String provider,String key,String media,long size,String checksum,String confidentiality,String supersedes,String actor,Instant at){super(a);monitoringCaseId=requiredText(c,"monitoringCaseId");monitoringUpdateId=requiredText(u,"monitoringUpdateId");commitmentItemId=requiredText(item,"commitmentItemId");originalFilename=requiredText(filename,"originalFilename");storageProvider=requiredText(provider,"storageProvider");storageObjectKey=requiredText(key,"storageObjectKey");mediaType=requiredText(media,"mediaType");if(size<1)throw new IllegalArgumentException("byteSize must be positive");byteSize=size;this.checksum=requiredText(checksum,"checksum");this.confidentiality=requiredText(confidentiality,"confidentiality");supersedesId=optionalText(supersedes);status=Status.ACTIVE;uploadedBy=requiredText(actor,"uploadedBy");uploadedAt=at;}public void supersede(){if(status!=Status.ACTIVE)throw new IllegalStateException("Only active evidence may be superseded");status=Status.SUPERSEDED;}public void voided(String reason){if(status!=Status.ACTIVE)throw new IllegalStateException("Only active evidence may be voided");status=Status.VOIDED;voidReason=requiredText(reason,"reason");}public String getMonitoringCaseId(){return monitoringCaseId;}public String getMonitoringUpdateId(){return monitoringUpdateId;}public String getCommitmentItemId(){return commitmentItemId;}public String getOriginalFilename(){return originalFilename;}public String getStorageProvider(){return storageProvider;}public String getStorageObjectKey(){return storageObjectKey;}public String getMediaType(){return mediaType;}public long getByteSize(){return byteSize;}public String getChecksum(){return checksum;}public String getConfidentiality(){return confidentiality;}public String getSupersedesId(){return supersedesId;}public Status getStatus(){return status;}public String getVoidReason(){return voidReason;}public String getUploadedBy(){return uploadedBy;}public Instant getUploadedAt(){return uploadedAt;}}
